package com.onebytelabs.zlplay;
import android.app.*;
import android.content.*;
import android.os.*;
import android.graphics.Bitmap;
import java.io.*;
import java.lang.reflect.*;
import com.onebytelabs.zlplay.project.*;
import com.onebytelabs.zlplay.audio.*;

/** Device-rendered review images with synthetic fixtures only; never saves user projects. */
public final class VisualReview {
 private static void set(Object o,String n,Object v)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}
 private static Object get(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 private static void call(Object o,String n,Class<?>[] types,Object... args){try{Method m=o.getClass().getDeclaredMethod(n,types);m.setAccessible(true);m.invoke(o,args);}catch(Exception e){throw new RuntimeException(e);}}
 private static void capture(Instrumentation test,File folder,String name)throws Exception{test.waitForIdleSync();Thread.sleep(350);Bitmap screenshot=test.getUiAutomation().takeScreenshot();if(screenshot==null)throw new AssertionError("Screen unavailable");try(FileOutputStream out=new FileOutputStream(new File(folder,name+".png"))){screenshot.compress(Bitmap.CompressFormat.PNG,100,out);}screenshot.recycle();}
 public static Bundle run(Instrumentation test)throws Exception{MainActivity screen=(MainActivity)test.startActivitySync(new Intent(test.getTargetContext(),MainActivity.class).putExtra("com.onebytelabs.zlplay.SKIP_RESTORE_TEST",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));File folder=new File(screen.getFilesDir(),"ui-review");folder.mkdirs();
  try{test.runOnMainSync(()->{try{SetlistSpec setlist=new SetlistSpec();setlist.title="Culto de domingo";for(String name:new String[]{"A Alegria do Senhor - Théo Rúbia","Primeira Essência - Felipe Rodrigues","Santo Pra Sempre - Gabriel Guedes"}){SetlistSpec.Song song=new SetlistSpec.Song();song.name=name;song.project="test.rpp";song.originalKey="D";song.tonalKey="D";setlist.songs.add(song);}set(screen,"setlist",setlist);set(screen,"setlistIndex",0);call(screen,"songHeading",new Class<?>[]{String.class},setlist.songs.get(0).name);call(screen,"renderSetlist",new Class<?>[]{});
   ProjectSpec spec=new ProjectSpec();spec.title=setlist.songs.get(0).name;spec.bpm=144;spec.duration=216;double[] bounds={0,23,52,74,106,131,150,196,216};String[] names={"Intro","Verso 1","Pré-refrão","Refrão","Verso 2","Ponte","Refrão","Final"},colors={"#bd9136","#337daf","#8150c5","#319a60","#337daf","#bd9136","#319a60","#8150c5"};for(int i=0;i<8;i++)spec.regions.add(new ProjectSpec.Region(names[i],bounds[i],bounds[i+1],colors[i]));String[] tracks={"Click","Guia","VS","Keys 1","Keys 2","Piano","AG","EG 1","EG 2","Bass","Drums","Loop","Perc","Vozes"};PcmTrack[] audio=new PcmTrack[tracks.length];for(int i=0;i<tracks.length;i++){ProjectSpec.Track track=new ProjectSpec.Track();track.name=tracks[i];spec.tracks.add(track);audio[i]=new PcmTrack(tracks[i],48000,1,new float[1]){@Override public double duration(){return 216;}};}DemoMixer mixer=(DemoMixer)get(screen,"mixer");mixer.load(audio);mixer.configureProject(spec);for(int i=0;i<tracks.length;i++)mixer.setGain(i,.35f+(i%6)*.08f);mixer.seek(86);set(screen,"activeProject",spec);set(screen,"projectKey","visual-review");call(screen,"configureSongKeys",new Class<?>[]{String.class},"Demo - Original (D).rpp");float[] peaks=new float[2048];for(int i=0;i<peaks.length;i++)peaks[i]=(float)(.06+.6*Math.abs(Math.sin(i*.517)*Math.sin(i*.073))+.12*Math.abs(Math.sin(i*.031)));set(screen,"sourcePeaks",peaks);call(screen,"renderMixer",new Class<?>[]{});((android.widget.EditText)get(screen,"bpmField")).setText(String.valueOf(mixer.getBpm()));
   }catch(Exception e){throw new RuntimeException(e);}});capture(test,folder,"main");test.runOnMainSync(()->{try{DemoMixer mixer=(DemoMixer)get(screen,"mixer");mixer.play();mixer.setLoop(true);mixer.selectRegion(2);}catch(Exception e){throw new RuntimeException(e);}});capture(test,folder,"regions-loop-jump");test.runOnMainSync(()->{try{DemoMixer mixer=(DemoMixer)get(screen,"mixer");mixer.pause();mixer.setLoop(false);}catch(Exception e){throw new RuntimeException(e);}});test.runOnMainSync(()->call(screen,"showMixer",new Class<?>[]{}));capture(test,folder,"mixer");test.runOnMainSync(()->{try{((Dialog)get(screen,"mixerDialog")).dismiss();}catch(Exception e){throw new RuntimeException(e);}});
   for(int i=0;i<3;i++){final int tab=i;test.runOnMainSync(()->call(screen,"showSettings",new Class<?>[]{int.class},tab));capture(test,folder,"settings-"+i);test.runOnMainSync(()->{try{((Dialog)get(screen,"settingsDialog")).dismiss();}catch(Exception e){throw new RuntimeException(e);}});}test.runOnMainSync(()->call(screen,"showRepertoire",new Class<?>[]{}));capture(test,folder,"setlist");test.runOnMainSync(()->{try{((Dialog)get(screen,"repertoireDialog")).dismiss();}catch(Exception e){throw new RuntimeException(e);}call(screen,"showMore",new Class<?>[]{});});capture(test,folder,"quick");test.runOnMainSync(()->{try{((Dialog)get(screen,"quickDialog")).dismiss();}catch(Exception e){throw new RuntimeException(e);}call(screen,"showLicenses",new Class<?>[]{});});capture(test,folder,"about");Bundle result=new Bundle();result.putString("status","PASS: six native screen captures with synthetic fixtures in files/ui-review");return result;
  }finally{test.runOnMainSync(screen::finish);}
 }
}
